window.B1_UNITS.push(
{ n:9, title:"REFIT", classes:"37–38", node:"Sector 09", color:"#e8a33d", theme:"Arranging for things to be done, and proposing ideas",
  overview:{
    intro:"You do not fix everything yourself. This sector covers the causative — get or have something done — which lets you say that you arranged a service rather than performed it, and then the full range of suggestion structures, from modals and gerunds to negative questions.",
    goals:["Use get / have something done to describe arranged services.","Distinguish the causative from the ordinary passive and the active.","Make suggestions with modals, gerunds, negative questions and infinitives."],
    outcome:"By the end you can describe six things you had done rather than did, and lead a five-minute planning discussion using a different suggestion structure each time."
  },
  vocab:[
    {term:"to get something done", pos:"causative", def:"to arrange for someone else to do something for you.",
     use:"“Get + object + past participle”: “I got my hair cut.” Slightly more informal than “have”.",
     examples:["I need to get the brakes checked.","We got the whole flat repainted."],
     colloc:"get it fixed · get your hair cut"},
    {term:"to have something done", pos:"causative", def:"the same idea, slightly more formal.",
     use:"“Have + object + past participle”: “We had the roof repaired.” Also used for bad experiences: “She had her bag stolen.”",
     examples:["We had the system upgraded last month.","He had his licence suspended."],
     colloc:"have it serviced · have it delivered"},
    {term:"to service", pos:"verb", def:"to check and maintain a machine or vehicle.",
     use:"Transitive: “service the engine”. Noun: “a service”, “due for a service”.",
     examples:["The van is being serviced today.","We have it serviced twice a year."],
     colloc:"have it serviced · a full service"},
    {term:"quote / estimate", pos:"nouns", def:"a stated price for a job before it is done.",
     use:"“Get a quote”, “ask for an estimate”. A quote is usually fixed; an estimate is approximate.",
     examples:["I got three quotes for the repair.","Their estimate was twice as high."],
     colloc:"get a quote · a rough estimate"},
    {term:"to install", pos:"verb", def:"to put equipment or software in place so it works.",
     use:"Transitive: “install a new panel”. Noun: installation.",
     examples:["We had solar panels installed.","The software is being installed remotely."],
     colloc:"have it installed · installation costs"},
    {term:"How about…?", pos:"expression", def:"a suggestion opener followed by -ing or a noun.",
     use:"“How about meeting at six?” Never followed by an infinitive.",
     examples:["How about starting an hour earlier?","How about Friday instead?"],
     colloc:"how about tomorrow · what about you"},
    {term:"Why don’t we…?", pos:"expression", def:"a friendly suggestion followed by a base verb.",
     use:"“Why don’t we ask them first?” The answer is usually “good idea” or a counter-proposal.",
     examples:["Why don’t we split the task?","Why don’t you ask your supervisor?"],
     colloc:"why don’t we · why not try"},
    {term:"worth a try", pos:"expression", def:"good enough to attempt.",
     use:"“It’s worth a try” or “it’s worth trying”. Never an infinitive.",
     examples:["It’s worth a try, at least.","That’s worth trying before we call support."],
     colloc:"well worth a try · worth trying"},
    {term:"to talk someone into / out of", pos:"phrasal verbs", def:"to persuade someone to do / not to do something.",
     use:"Followed by a noun or -ing: “talked me into buying it”, “talked her out of resigning”.",
     examples:["She talked me into getting it repaired instead.","I talked him out of doing it himself."],
     colloc:"talk someone into it · talk yourself out of"},
    {term:"to go ahead", pos:"phrasal verb", def:"to proceed with a plan.",
     use:"Intransitive, often with “with”: “go ahead with the repair”. Also a permission phrase: “Go ahead.”",
     examples:["We decided to go ahead with the upgrade.","Shall I book it? — Go ahead."],
     colloc:"go ahead with the plan · give the go-ahead"} ],
  grammar:[
    {name:"Get or have something done", short:"I had the engine serviced. / We’re getting the panel replaced.",
     rule:"The causative says that you arranged for someone else to do the work. The structure is “have” or “get” plus the object plus a past participle. The person who did the job is normally left out entirely.",
     form:["have + object + past participle → We had the roof repaired.","get + object + past participle → I’m getting my laptop fixed.","All tenses on have/get: I’ve had it serviced. / I’ll get it checked. / I was having it repaired.","Question / negative: Did you have it delivered? / We haven’t had it inspected yet.","Naming the worker (rare): We had a technician check the wiring. (active: no participle)"],
     notes:["Compare three sentences: “I repaired the car” (I did it), “I had the car repaired” (someone did it for me), “The car was repaired” (passive, no mention of arrangement).","“Get” is slightly more informal and often implies more effort or persuasion; “have” is neutral.","With “have + person + base verb” the worker is named and the verb is active: “I had the plumber look at it.”","The causative also reports things done to you that you did not want: “She had her bag stolen.”","Do not use an infinitive: “I had the car to repair” means something completely different."],
     deep:"The causative exists because English needs to distinguish doing from arranging, and most languages mark that difference with a separate verb. “I cut my hair” means you held the scissors; “I had my hair cut” means you sat in a chair while somebody else did. That distinction matters more than it looks, because at B1 learners routinely claim to have rewired their own flat or serviced their own car. The structure is mechanically simple — object first, participle second — and the tense is carried entirely by “have” or “get”, so all the usual forms are available. Two extras are worth knowing. “Have + person + base verb” names the worker and switches to an active infinitive, which is useful when the person matters. And the same structure reports misfortune, so “he had his licence suspended” arranges nothing at all — context tells your listener which reading applies.",
     chart:{title:"Who did the work?", cols:["Sentence","Who acted","Meaning"], rows:[["I painted the flat.","you","you did the work"],["I had the flat painted.","someone else","you arranged it"],["I got the flat painted.","someone else","you arranged it (informal)"],["The flat was painted.","unspecified","plain passive"],["I had a decorator paint it.","named person","active infinitive"],["She had her bag stolen.","a thief","misfortune, not arranged"]]},
     examples:["We’re having the navigation system upgraded next week.","I got my documents translated because I couldn’t do it myself.","Have you had the brakes checked since the trip?","They had their contract cancelled without any warning."],
     watch:"Use a past participle, not an infinitive: “I had it repaired”, never “I had it to repair”."},
    {name:"Making suggestions with modals, gerunds, negative questions and infinitives", short:"We could ask. How about asking? Why don’t we ask? It might be worth asking.",
     rule:"English has a graded set of suggestion structures. Modals propose an option, gerund frames propose an activity, negative questions invite agreement, and infinitive frames make the suggestion impersonal.",
     form:["Modal: We could / should / might ask them first.","Gerund frames: How about asking them? / What about a different supplier?","Negative question: Why don’t we ask them? / Couldn’t we ask them?","Infinitive frame: It might be better to ask them. / The best thing to do is to ask.","Shared action: Let’s ask them. / Shall we ask them?"],
     notes:["“How about” and “What about” take a gerund or a noun, never an infinitive: “How about meeting?”, not “How about to meet”.","“Why don’t we” takes a base verb: “Why don’t we start now?”","Negative questions expect agreement, which makes them softer than a bare imperative but stronger than “could”.","“Suggest” and “recommend” never take an object plus infinitive: say “I suggest asking” or “I suggest that we ask”, never “I suggest us to ask”.","“Shall we…?” is a genuine invitation to decide together, and it is more common in British English."],
     deep:"Suggestions are the same content at different social temperatures, and choosing the temperature is the real skill. “We could ask them” offers an option and leaves the decision open. “Why don’t we ask them?” presents your idea as the obvious next step and invites agreement, so it is warmer but more directive. “It might be better to ask them” removes you from the sentence entirely, turning the suggestion into a general observation — the safest form when you are contradicting someone senior. In a meeting, moving through these forms keeps you from sounding either passive or pushy. Two mechanics protect the structures: gerunds after “how about” and “what about”, base verbs after “why don’t”. And remember that “suggest” resists the object-plus-infinitive pattern, which is one of the most persistent errors carried up from A2.",
     chart:{title:"Suggestion structures by temperature", cols:["Structure","Followed by","Force","Example"], rows:[["We could…","base verb","option","We could postpone it."],["How about…?","gerund / noun","friendly proposal","How about postponing it?"],["Why don’t we…?","base verb","expects agreement","Why don’t we postpone it?"],["Shall we…?","base verb","joint decision","Shall we postpone it?"],["It might be better to…","infinitive","impersonal advice","It might be better to postpone."],["I suggest…","gerund / that-clause","personal proposal","I suggest postponing it."]]},
     examples:["How about getting a second quote before we decide?","Why don’t we have it serviced while the bay is free?","It might be better to replace the whole unit than to keep repairing it.","Couldn’t we ask the supplier to send a technician?"],
     watch:"“How about” takes -ing, “why don’t we” takes a base verb, and “I suggest” never takes “us to”."} ],
  speaking:[
    {kind:"Did you or did you have it done?", text:"List eight things that happened to your home, car or devices last year. Your partner asks whether you did each one or had it done."},
    {kind:"Planning meeting", text:"Plan an event in five minutes. Every contribution must use a different suggestion structure, and nobody may repeat one."},
    {kind:"Persuasion", text:"Try to talk your partner into a plan they dislike, escalating from “we could” to “why don’t we” to “it might be better to”."} ],
  tips:[
    "Causative = have/get + object + past participle.",
    "“How about” + -ing; “why don’t we” + base verb.",
    "“I suggest asking” or “I suggest that we ask” — never “I suggest us to ask”."],
  quiz:{q:"We’re going to ___ the whole system ___ next month.", options:["have / upgraded","have / upgrade","get / to upgrade"], answer:0, explain:"The causative takes an object followed by a past participle: “have the system upgraded”."} },

{ n:10, title:"TRAJECTORY", classes:"41–42", node:"Sector 10", color:"#4fd18b", theme:"Predicting what lies ahead and locating what lies behind",
  overview:{
    intro:"Navigation runs in both directions. This sector gives you three future forms for prediction — will, the future continuous and the future perfect — and then the whole set of adverbs and prepositions for placing an event accurately in the past.",
    goals:["Predict with will, the future continuous and the future perfect.","Choose the right future form for a moment, an ongoing action and a completed one.","Refer to past time precisely with during, in, ago, from…to, for and since."],
    outcome:"By the end you can describe your life five years from now in three future forms, and give a precise timeline of the last five years."
  },
  vocab:[
    {term:"to be likely to", pos:"expression", def:"probable.",
     use:"“Be likely to + verb” or “It’s likely that…”. Opposite: “unlikely”.",
     examples:["Prices are likely to rise next year.","She’s unlikely to accept the offer."],
     colloc:"highly likely · likely outcome"},
    {term:"by then / by that time", pos:"adverbial phrases", def:"before or at that future moment.",
     use:"Strong triggers for the future perfect: “By then we’ll have finished.”",
     examples:["By then I’ll have graduated.","By that time the system will have been replaced."],
     colloc:"by then · by the end of the year"},
    {term:"for the time being", pos:"adverbial phrase", def:"for now, until the situation changes.",
     use:"Usually at the start or the end: “For the time being, we’re staying put.”",
     examples:["For the time being, nothing changes.","We’ll use the old version for the time being."],
     colloc:"for the time being · for now"},
    {term:"during", pos:"preposition", def:"at some point within a period of time.",
     use:"Followed by a noun, never a clause: “during the meeting”, not “during it rained”.",
     examples:["It happened during the night shift.","I studied abroad during my second year."],
     colloc:"during the summer · during the meeting"},
    {term:"ago", pos:"adverb", def:"before now, counting backwards.",
     use:"Always after the time period, and always with the simple past: “two years ago”.",
     examples:["I met her three months ago.","We moved here a long time ago."],
     colloc:"a while ago · not long ago"},
    {term:"from … to …", pos:"prepositions", def:"marking a start point and an end point.",
     use:"“From 2019 to 2022”. In American English “from Monday through Friday” includes Friday.",
     examples:["I worked there from 2018 to 2021.","The bay is closed from nine to five."],
     colloc:"from Monday to Friday · from start to finish"},
    {term:"milestone", pos:"noun", def:"an important point in a plan or a life.",
     use:"Countable: “reach a milestone”. Common in goal-setting.",
     examples:["The next milestone is the pressure test.","It was a real milestone for the team."],
     colloc:"reach a milestone · a major milestone"},
    {term:"to look ahead", pos:"phrasal verb", def:"to think about the future.",
     use:"Intransitive, often with “to”: “looking ahead to next year”.",
     examples:["Looking ahead, I’d like to specialise.","Let’s look ahead to the next phase."],
     colloc:"look ahead to · looking further ahead"},
    {term:"eventually", pos:"adverb", def:"in the end, after some time.",
     use:"Not the same as “possibly”. Useful in future narratives: “Eventually we’ll automate it.”",
     examples:["Eventually they’ll replace the whole fleet.","She eventually agreed."],
     colloc:"eventually happen · eventually replaced"},
    {term:"to be on track", pos:"idiom", def:"progressing as planned.",
     use:"With “be”, often with “to + verb” or “for + noun”: “on track to finish by June”.",
     examples:["We’re on track to finish ahead of schedule.","The project is back on track."],
     colloc:"on track to finish · back on track"} ],
  grammar:[
    {name:"Predicting the future with will, the future continuous and the future perfect", short:"I’ll be working. / By June I’ll have finished.",
     rule:"Three forms describe three shapes of future. “Will” states a prediction or a decision. The future continuous describes an action in progress at a future moment. The future perfect describes an action completed before a future deadline.",
     form:["will + base verb → Prices will rise next year.","will be + -ing → At ten tomorrow I’ll be flying.","will have + past participle → By December I’ll have finished the course.","will have been + -ing (duration) → By May I’ll have been working here a year.","Negative / question: won’t be working · Will you have finished by then?"],
     notes:["Time markers do most of the work: “at ten tomorrow” pulls the continuous, “by December” pulls the perfect.","The future continuous is also a polite way of asking about plans without sounding like a request: “Will you be using the car tonight?”","After “by the time”, the verb stays in the present: “By the time you arrive, we’ll have started.”","State verbs stay simple: “I’ll have known her for ten years”, not “will have been knowing”.","“Going to” remains the form for a plan already decided; these three are for prediction and projection."],
     deep:"Once you have more than one future form, the time expression usually chooses for you. A point in time — “at nine tomorrow”, “this time next week” — asks what will be in progress then, so it takes the continuous. A deadline — “by Friday”, “by the end of the quarter” — asks what will be complete before it, so it takes the perfect. Bare “will” has no shape at all, which is why it suits general predictions and instant decisions. The future perfect is the form most learners avoid and the one that most raises the level of a plan, because it lets you look back from a point you have not reached yet: “by the time the audit starts, we’ll have replaced both units.” Note the recurring rule about time clauses — no future form after “by the time”, “when” or “as soon as” — which applies here exactly as it did in sector 08.",
     chart:{title:"Which future form?", cols:["Time marker","Form","Example"], rows:[["next year, one day","will","Prices will rise."],["at nine tomorrow, this time next week","will be + -ing","I’ll be travelling then."],["by Friday, by then, by the end of…","will have + participle","I’ll have finished by then."],["by June + duration","will have been + -ing","I’ll have been working here a year."],["already decided plan","be going to","I’m going to apply."],["fixed arrangement","present continuous","I’m meeting them at four."]]},
     examples:["This time next month I’ll be working in a different department.","By the end of the year we’ll have replaced every unit in the fleet.","I don’t think prices will fall, but they probably won’t rise much either.","Will you be using the simulator this afternoon? I need an hour on it."],
     watch:"No future form after “by the time”: “By the time you arrive, we’ll have started”, not “will arrive”."},
    {name:"Referring to time in the past: during, in, ago, from…to, for, since", short:"during the summer · in 2019 · two years ago · for six months · since March",
     rule:"Each of these expressions locates a past event differently: some name a period, some a point, some a duration, and some a starting point. Their grammar is fixed, and the tense they take is part of the pattern.",
     form:["during + noun (period) → It happened during the night.","in + month / year / season → We met in 2019.","on + day / date → We signed on 3 May.","ago + simple past → I left two years ago.","from … to … → I worked there from 2018 to 2021.","for + duration → I worked there for three years.","since + starting point + present perfect → I’ve worked here since March."],
     notes:["“During” takes a noun; for a clause use “while”: “during the flight” but “while we were flying”.","“Ago” goes after the period and only with the simple past — never with the present perfect.","“For” answers “how long?” and works with several tenses; “since” gives a starting point and normally requires the present perfect.","“From … to …” marks a closed period, so it takes the simple past: “from 2018 to 2021 I worked…”.","“In” is also used for a future interval: “in two weeks” means two weeks from now, not two weeks ago."],
     deep:"Time reference is where accurate B1 writing is won or lost, because these words are fixed and a wrong one is noticed immediately. Group them by what they measure. “During”, “in” and “on” locate an event inside a period, in decreasing size. “Ago” and “from … to …” both describe closed time and therefore both take the simple past. “For” measures duration and can appear with almost any tense, while “since” names a starting point and pulls the present perfect with it, because a starting point implies the situation continues. The pair that causes most trouble is “for” and “since”, and the fix is to look at what follows rather than at the meaning: a length of time takes “for”, a point on the calendar takes “since”. Note also that “ago” and “since” are mutually exclusive — “since two years ago” is a mix of two systems.",
     chart:{title:"Past time expressions", cols:["Expression","Followed by","Typical tense","Example"], rows:[["during","noun (period)","past simple","It failed during the test."],["in","month / year / season","past simple","We launched in 2020."],["on","day / date","past simple","It arrived on Tuesday."],["ago","period + ago","past simple","I applied six weeks ago."],["from … to …","two points","past simple","I studied there from 2016 to 2019."],["for","duration","several tenses","I lived there for two years."],["since","starting point","present perfect","I’ve lived here since 2019."]]},
     examples:["I worked in the maintenance division from 2017 to 2020, and I’ve been in operations since then.","The fault appeared during the second test, about ten minutes ago.","We’ve had the same equipment for six years, and nothing has failed since the upgrade.","In March we replaced the sensors; on 12 April the whole unit failed anyway."],
     watch:"“For” + duration, “since” + starting point, and never “since two years ago”."} ],
  speaking:[
    {kind:"Five years out", text:"Describe your life five years from now in six sentences: two with will, two with the future continuous, two with the future perfect."},
    {kind:"Timeline", text:"Give a precise five-year timeline of your studies or career, using during, in, ago, from…to, for and since at least once each."},
    {kind:"Projections", text:"In pairs, predict three changes in your field. For each one say what will be happening and what will have happened by a stated deadline."} ],
  tips:[
    "A point in time pulls the continuous; a deadline pulls the perfect.",
    "“Ago” only with the simple past; “since” only with the perfect.",
    "No future form after “by the time”."],
  quiz:{q:"By the time the inspection starts, we ___ every panel.", options:["will have checked","will check","will be checking"], answer:0, explain:"An action completed before a future deadline takes the future perfect, and “by the time” keeps its own clause in the present."} },

{ n:11, title:"REROUTE", classes:"46–47", node:"Sector 11", color:"#e0554a", theme:"Sequencing events, and regretting the route you took",
  overview:{
    intro:"Two structures that both depend on control of time. Time clauses order events precisely — before, after, once, the moment, as soon as, until, by the time — and then the unreal past lets you regret a decision and imagine the journey you did not take.",
    goals:["Use time clauses with the correct tense in past, present and future reference.","Express regret with should (not) have + past participle.","Build third conditional sentences with if + past perfect and would/could have + past participle."],
    outcome:"By the end you can narrate a sequence of events with five different time conjunctions, and review a past decision with regret and a hypothetical alternative."
  },
  vocab:[
    {term:"the moment", pos:"conjunction", def:"immediately when; as soon as.",
     use:"Works as a conjunction: “Call me the moment you land.” Also “the minute”, “the second”.",
     examples:["The moment I saw the reading, I knew.","Let me know the moment it arrives."],
     colloc:"the moment you arrive · the minute I saw it"},
    {term:"once", pos:"conjunction", def:"as soon as; after something has happened.",
     use:"Followed by a clause with a present or past tense, never a future: “once we know”.",
     examples:["Once the checks are complete, we can launch.","Once I’d read the report, everything made sense."],
     colloc:"once we know · once it’s finished"},
    {term:"until", pos:"conjunction / preposition", def:"up to the moment when.",
     use:"Marks an end point, not a duration. With a negative it means “not before”: “Don’t leave until I call.”",
     examples:["We waited until the storm passed.","I won’t decide until I speak to her."],
     colloc:"until now · not until · up until then"},
    {term:"to regret", pos:"verb", def:"to feel sorry about something you did or did not do.",
     use:"“Regret + -ing” for the past action: “I regret sending it.” “Regret to inform” is a formal announcement.",
     examples:["I regret not taking that offer.","She regrets telling him."],
     colloc:"deeply regret · no regrets"},
    {term:"to turn down", pos:"phrasal verb", def:"to refuse an offer.",
     use:"Separable: “turn down the offer”, “turn it down”. Also “reduce the volume”.",
     examples:["I turned down the job and I still think about it.","They turned our proposal down."],
     colloc:"turn down an offer · turn it down"},
    {term:"in hindsight", pos:"adverbial phrase", def:"looking back with what you know now.",
     use:"Usually opens the sentence and pairs with past modals: “In hindsight, I should have waited.”",
     examples:["In hindsight, the signs were obvious.","With hindsight, we moved too fast."],
     colloc:"in hindsight · with the benefit of hindsight"},
    {term:"to blame", pos:"verb", def:"to say someone is responsible for something bad.",
     use:"“Blame someone for something”. “To be to blame” = to be responsible.",
     examples:["Don’t blame me for the delay.","Nobody was to blame."],
     colloc:"take the blame · who’s to blame"},
    {term:"otherwise", pos:"adverb", def:"if not; in the other case.",
     use:"Links a condition to a consequence across two clauses: “Write it down; otherwise you’ll forget.”",
     examples:["Leave now, otherwise you’ll miss it.","She apologised; otherwise I’d have complained."],
     colloc:"otherwise fine · or otherwise"},
    {term:"lesson", pos:"noun", def:"something you learn from an experience.",
     use:"“Learn a lesson”, “an expensive lesson”. Useful for closing a regret story.",
     examples:["It was an expensive lesson.","I learnt my lesson that day."],
     colloc:"a hard lesson · learn your lesson"},
    {term:"instead of", pos:"preposition", def:"in place of.",
     use:"Followed by a noun or -ing: “instead of waiting”. Never an infinitive.",
     examples:["I should have called instead of sending an email.","Instead of complaining, we rebuilt it."],
     colloc:"instead of that · rather than"} ],
  grammar:[
    {name:"Time clauses: before, after, once, the moment, as soon as, until, by the time", short:"As soon as I finish, I’ll call you.",
     rule:"A time clause says when the main action happens. It can come first or second; if it comes first, it takes a comma. English never puts a future form inside a time clause — the future lives only in the main clause.",
     form:["Future reference: As soon as I finish, I’ll send it. (present simple in the clause)","Stressing completion: Once I’ve finished, I’ll send it. (present perfect)","Past sequence: After I sent it, she called.","Earlier past event: By the time we arrived, it had closed.","Reduced with -ing (same subject): Before leaving, check the lights."],
     notes:["This is the rule examiners look for: “when I will arrive” is always wrong. Use the present simple.","“Until” marks an end point and often appears with a negative main clause: “I won’t decide until I hear from them.”","“By the time” usually pulls the past perfect in past narration and the future perfect in future reference.","“As soon as”, “the moment” and “once” all mean there is no gap between the two events; “after” allows one.","A reduced -ing clause is only possible when both clauses share the same subject."],
     deep:"Time clauses look easy and then quietly break sentences, because they run on a rule that feels illogical: the clause refers to the future but its verb is in the present. The reason is that English marks the future only once. The main clause carries “will” or “going to”, and the conjunction — when, once, as soon as, until — already tells you where you are, so the subordinate clause does not repeat the marking. Spanish uses a subjunctive in exactly this slot, which is why the error is so persistent. The second skill is conjunction choice, because it encodes your reading of events: “when the alarm sounded, we left” (sequence), “as soon as the alarm sounded, we left” (immediately), “once the alarm had sounded, we left” (after completion), “we waited until the alarm sounded” (end point). Same facts, four different stories.",
     chart:{title:"Tense inside time clauses", cols:["Reference","Time clause","Main clause"], rows:[["Future","present simple: as soon as I finish","will: I’ll call you"],["Future, completion stressed","present perfect: once I’ve finished","will: I’ll call you"],["Future deadline","present: by the time you arrive","future perfect: we’ll have started"],["Present habit","present: when I get home","present: I make coffee"],["Past sequence","past simple: after I sent it","past simple: she called"],["Past, earlier event","past simple: by the time we arrived","past perfect: it had closed"]]},
     examples:["I’ll forward the report as soon as I’ve checked the figures.","Once the tests are complete, the bay will be reopened.","By the time the engineers got there, the leak had already stopped.","We won’t change anything until we understand what caused it."],
     watch:"Never put “will” in a time clause: “when I arrive”, not “when I will arrive”."},
    {name:"Regret with should (not) have; hypothetical past with if + past perfect", short:"I should have checked. / If I had checked, this wouldn’t have happened.",
     rule:"To comment on a past you cannot change, English adds “have + past participle” to a modal. “Should have” expresses regret or criticism. The third conditional puts an unreal past condition with the past perfect and an unreal past result with would/could/might have + participle.",
     form:["Regret: I should have booked earlier. (I didn’t.)","Criticism: You shouldn’t have said that. (You did.)","Third conditional: If I had checked the log, I would have seen the error.","Other results: could have (possibility) · might have (uncertain outcome).","Reversed order, no comma: I would have seen the error if I had checked the log."],
     notes:["The pattern is always modal + have + participle: never “should had” and never “should of”, which is a spelling of the spoken “should’ve”.","“Should have” criticises the past; “should” alone advises the present: “You should call her” versus “You should have called her”.","No “would” in the if-clause: “If I would have known” is wrong. The condition takes the past perfect.","“Could have” has two meanings — an unrealised possibility (“we could have won”) and a past deduction (“she could have forgotten”).","In speech these all contract heavily: should’ve, would’ve, could’ve, hadn’t. Train your ear for them."],
     deep:"The unreal past is one step further back than the unreal present, and that extra step is what makes it impossible to change. “If I had time, I would help” imagines a different now; “if I had had time, I would have helped” imagines a different then, and no action can alter it. That is why the third conditional is the grammar of post-mortems, and why it pairs so naturally with “should have”. The two structures say related things with different emphasis: “I should have checked” admits fault, while “if I had checked, this wouldn’t have happened” traces the consequence. Two traps recur at B1. “Would” never appears in the if-clause — the condition is marked by the past perfect alone. And the written form is “should have” or “should’ve”; “should of” appears only because the spoken contraction sounds like it, and it is always wrong on paper.",
     chart:{title:"Regret and the third conditional", cols:["Form","Reality","Meaning"], rows:[["I should have checked.","I didn’t.","regret"],["You shouldn’t have signed.","You did.","criticism"],["I would have helped.","I didn’t (no chance).","unrealised intention"],["We could have avoided it.","We didn’t.","missed possibility"],["If I had known, I would have called.","I didn’t know.","third conditional"],["If we hadn’t left late, we wouldn’t have missed it.","We left late.","negative condition"]]},
     examples:["I should have run the diagnostics before signing off on the repair.","You shouldn’t have paid in cash — now there’s no record.","If we had ordered the part in March, it would have arrived before the refit.","They could have avoided the whole delay if somebody had read the manual."],
     watch:"Write “should have” or “should’ve”, never “should of”, and keep “would” out of the if-clause."} ],
  speaking:[
    {kind:"Sequence relay", text:"Build a group story where each student adds one sentence beginning with a different time conjunction: before, after, once, the moment, as soon as, until, by the time."},
    {kind:"Post-mortem", text:"Review a plan that went wrong. Each person contributes one “should have”, one “could have” and one full third conditional."},
    {kind:"Alternative history", text:"Choose one decision from your past and describe three consequences that would have followed if you had chosen differently."} ],
  tips:[
    "Time clause = present tense, even for the future.",
    "Modal + have + participle. Never “should of”.",
    "The if-clause of a third conditional takes the past perfect, never “would”."],
  quiz:{q:"If we ___ the part earlier, it would have arrived on time.", options:["had ordered","would order","ordered"], answer:0, explain:"A third conditional takes the past perfect in the if-clause and “would have + participle” in the result."} },

{ n:12, title:"MANIFEST", classes:"50–51", node:"Sector 12", color:"#5bc8f5", theme:"Saying what something is for and why it happened",
  overview:{
    intro:"Every entry on a manifest answers two questions: what is it for, and why is it here. This sector gives you purpose — infinitive clauses, including the version with “for” when the purpose belongs to somebody else — and the full inventory of reason connectors, each with its own grammar.",
    goals:["Express purpose with infinitive clauses and with for + object + infinitive.","Distinguish purpose (why) from function (what for).","Give reasons with because, since, because of, for, due to and the reason."],
    outcome:"By the end you can explain the purpose of six objects or decisions and justify each one with a different reason connector."
  },
  vocab:[
    {term:"purpose", pos:"noun", def:"the reason why something exists or is done.",
     use:"“The purpose of X is to + verb”. “On purpose” means deliberately — a different meaning.",
     examples:["The purpose of the checklist is to catch small errors.","He did it on purpose."],
     colloc:"the main purpose · serve a purpose"},
    {term:"to be intended for", pos:"expression", def:"designed for a particular use or group.",
     use:"Passive with “for + noun” or “to + verb”: “intended for professional use”.",
     examples:["This tool is intended for heavy-duty work.","The guide is intended to help newcomers."],
     colloc:"intended for use in · intended audience"},
    {term:"due to", pos:"preposition", def:"because of.",
     use:"Followed by a noun or -ing, never a clause: “due to a fault”.",
     examples:["The delay was due to a technical fault.","Due to demand, we added a session."],
     colloc:"due to bad weather · largely due to"},
    {term:"owing to", pos:"preposition", def:"a slightly more formal “because of”.",
     use:"Followed by a noun: “owing to heavy rain”. Common in announcements.",
     examples:["Owing to the storm, all flights were grounded.","Owing to staff shortages, the desk is closed."],
     colloc:"owing to circumstances"},
    {term:"the reason why", pos:"noun phrase", def:"the explanation for something.",
     use:"“The reason why X is that…” or “the reason for + noun”. Note “is that”, not “is because”.",
     examples:["The reason why I called is that nobody answered the email.","The reason for the delay is unclear."],
     colloc:"the main reason why · for that reason"},
    {term:"to justify", pos:"verb", def:"to give good reasons for something.",
     use:"Followed by a noun or -ing: “justify the cost”, “justify spending more”. Never an infinitive.",
     examples:["The results justify the extra expense.","How do you justify raising the price?"],
     colloc:"hard to justify · justify a decision"},
    {term:"rationale", pos:"noun", def:"the underlying reason for a decision.",
     use:"Formal, countable: “the rationale behind the change”.",
     examples:["Nobody explained the rationale behind the new rule.","The rationale is purely financial."],
     colloc:"the rationale behind · a clear rationale"},
    {term:"so that", pos:"conjunction", def:"in order that — followed by a clause.",
     use:"Use it when the purpose has a different subject or needs a modal: “so that everyone can see”.",
     examples:["We moved the briefing so that the night crew could attend.","Label it so that nobody uses the wrong one."],
     colloc:"so that everyone can · so as to"},
    {term:"to avoid", pos:"verb", def:"to prevent or stay away from something.",
     use:"Followed by a noun or -ing, never an infinitive: “avoid making mistakes”.",
     examples:["We left early to avoid the traffic.","Avoid clicking unknown links."],
     colloc:"avoid a problem · hard to avoid"},
    {term:"thereby", pos:"adverb", def:"and as a result of that (formal).",
     use:"Followed by -ing in written English: “thereby reducing costs”. Rare in speech.",
     examples:["We automated the checks, thereby cutting the time in half.","It failed, thereby delaying everything."],
     colloc:"thereby reducing · thereby avoiding"} ],
  grammar:[
    {name:"Describing purpose with infinitive clauses and with for", short:"We stopped to refuel. / We stopped for the crew to rest.",
     rule:"Purpose answers “why?”. The default form is “to + verb”, raised in register by “in order to” and “so as to”. When the purpose belongs to a different subject, English uses “for + object + infinitive”, or a clause with “so that”.",
     form:["to + verb → I called to confirm the booking.","in order to / so as to + verb → We left early in order to avoid the traffic.","Negative: in order not to / so as not to → I whispered so as not to wake her.","for + object + infinitive → We stopped for the crew to rest.","so that + clause → We moved it so that the night shift could attend.","for + noun (function) → This key is for the side door."],
     notes:["Never write “for + infinitive”: “for to open” and “I came for see you” are both wrong.","Function takes “for + -ing” or “to + verb”: “used for storing data” / “used to store data”. Both are correct.","Use “for + object + infinitive” when the person acting is not the subject of the main clause.","“So that” is the choice when the purpose clause needs a modal — can, could, would — or a different subject.","The negative purpose form is “in order not to”, not “to not”."],
     deep:"Purpose is the most common thing you will ever need to express in a technical or professional context, and English gives you a scale of forms rather than a single one. A bare “to + verb” is neutral and covers most cases. “In order to” and “so as to” raise the register and are useful in writing, and they are the only forms that comfortably take the negative — “in order not to lose data”. The structure that unlocks real precision is “for + object + infinitive”, because it names whose purpose is being served: “we rescheduled the drill for the new crew to take part” tells you something that “we rescheduled the drill to take part” cannot. When the purpose needs a modal, switch to “so that”, which accepts a full clause: “label the containers so that nobody can mix them up.” Between them, these four forms handle every purpose you will need to express.",
     chart:{title:"Expressing purpose", cols:["Structure","When to use","Example"], rows:[["to + verb","same subject, neutral","I called to confirm."],["in order to / so as to","formal register","We left early in order to avoid delays."],["in order not to / so as not to","negative purpose","I wrote so as not to forget."],["for + object + infinitive","different subject","We waited for the engineer to arrive."],["so that + clause","needs a modal or new subject","Move it so that everyone can see."],["for + -ing","function of a thing","This valve is for releasing pressure."]]},
     examples:["The bay was cleared in order to give the technicians room to work.","We printed a second copy for the auditors to take away.","Label every container so that nobody can confuse them.","This panel is for accessing the coolant lines, not for storage."],
     watch:"Never “for + infinitive”. Purpose is “to do”; function is “for doing”; a different subject takes “for someone to do”."},
    {name:"Giving reasons with because, since, because of, for, due to and the reason", short:"because it failed / because of the failure / the reason is that…",
     rule:"Reason connectors differ in grammar more than in meaning, and the category decides the punctuation. Conjunctions take clauses, prepositions take nouns, and the noun-phrase frames take a that-clause.",
     form:["because + clause → We stopped because the pump failed.","since / as + clause (known reason, often first) → Since nobody replied, I decided myself.","because of / due to / owing to + noun → We stopped due to a pump failure.","as a result of + noun → Two flights were cancelled as a result of the storm.","The reason why … is that … → The reason why we stopped is that the pump failed.","so + clause (result, mirror image) → The pump failed, so we stopped."],
     notes:["“Because of”, “due to” and “owing to” must be followed by a noun or gerund: “due to it failed” is wrong.","“Since” and “as” present the reason as already known and usually come first; “because” carries new information and usually comes second.","Write “the reason is that”, not “the reason is because” — the latter is redundant.","“So” introduces the result, “because” the cause: they are mirror images of the same relationship.","“For” meaning “because” is literary and easily misused at this level; prefer “because” or “since”."],
     deep:"Cause and result are two views of one relationship, and which half you put in the main clause changes what your reader treats as important, because English weights the second clause more heavily. “The flight was cancelled, so we stayed another night” foregrounds the outcome; “we stayed another night because the flight was cancelled” foregrounds the explanation. Use that deliberately. The mechanical trap is category confusion: if you can see a subject and a verb after the connector, you need “because”, “since” or “as”; if you can see only a noun phrase, you need “because of”, “due to” or “owing to”. The frame “the reason why … is that …” is worth having because it announces that an explanation is coming, which is useful in a long sentence — but keep “is that”, since “the reason is because” says the same thing twice.",
     chart:{title:"Reason and result connectors", cols:["Connector","Category","Followed by","Example"], rows:[["because","conjunction","clause","We stopped because it failed."],["since / as","conjunction","clause (known reason)","Since it failed, we stopped."],["because of","preposition","noun / -ing","We stopped because of the failure."],["due to / owing to","preposition","noun","The delay was due to the failure."],["as a result of","preposition","noun","It closed as a result of the fault."],["the reason … is that","noun frame","that-clause","The reason we stopped is that it failed."],["so","coordinator","clause (result)","It failed, so we stopped."]]},
     examples:["We rescheduled the test because the pressure readings were unstable.","Owing to a shortage of parts, the refit has been pushed back two weeks.","Since nobody had signed the form, the request was never processed.","The reason why we changed supplier is that the last delivery arrived damaged."],
     watch:"“Because” + clause, “because of / due to” + noun, and “the reason is that”, never “the reason is because”."} ],
  speaking:[
    {kind:"What’s it for?", text:"Explain the purpose of six objects around you. Use “to + verb” for three and “for + -ing” for three, then add one purpose with “for someone to”."},
    {kind:"Justify it", text:"Defend six decisions you have made, each with a different reason connector. Your partner corrects any category error."},
    {kind:"Design brief", text:"Describe a tool or app you would build: what each feature is for, who it is for, and why the design is as it is."} ],
  tips:[
    "Purpose = “to do”; function = “for doing”; different subject = “for someone to do”.",
    "“Because” + clause, “due to” + noun.",
    "“The reason is that”, never “the reason is because”."],
  quiz:{q:"The launch was postponed ___ a fault in the fuel line.", options:["due to","because","so that"], answer:0, explain:"“Due to” is a preposition and takes a noun phrase; “because” would require a full clause."} },

{ n:13, title:"FORENSICS", classes:"55–56", node:"Sector 13", color:"#e8a33d", theme:"Deducing what happened, and judging what should have happened",
  overview:{
    intro:"Two uses of the same machinery. Past modals let you deduce what happened when you were not there — must have, may have, might have, could have — and then judge the decisions that were taken: should have, could have, would have. One reads the evidence; the other reads the choices.",
    goals:["Express degrees of certainty about the past with must, may, might and could + have.","Use can’t have and couldn’t have for confident negative deductions.","Judge past actions with should have, could have and would have."],
    outcome:"By the end you can analyse an incident at three levels of certainty and deliver a fair judgement on the decisions involved."
  },
  vocab:[
    {term:"evidence", pos:"noun", def:"facts that show something is true.",
     use:"Uncountable: “some evidence”, “a piece of evidence”, never “evidences”.",
     examples:["There’s no evidence that anyone tampered with it.","The evidence suggests a software fault."],
     colloc:"clear evidence · lack of evidence"},
    {term:"to assume", pos:"verb", def:"to accept something as true without checking.",
     use:"Followed by a that-clause: “I assumed you knew.” Noun: assumption.",
     examples:["I assumed the checks had been done.","Don’t assume anything."],
     colloc:"safe to assume · a reasonable assumption"},
    {term:"to rule out", pos:"phrasal verb", def:"to decide that something is not the cause.",
     use:"Separable: “rule out human error”, “rule it out”.",
     examples:["We can rule out a power failure.","Nothing has been ruled out yet."],
     colloc:"rule out a cause · can’t rule it out"},
    {term:"plausible", pos:"adjective", def:"believable, reasonable as an explanation.",
     use:"For explanations and accounts: “a plausible theory”. Opposite: implausible.",
     examples:["That’s the most plausible explanation.","His account isn’t plausible."],
     colloc:"a plausible explanation · perfectly plausible"},
    {term:"to overlook", pos:"verb", def:"to fail to notice something.",
     use:"Transitive. Not the same as “oversee”, which means to supervise.",
     examples:["Somebody must have overlooked the warning.","One detail was overlooked."],
     colloc:"easily overlooked · overlook an error"},
    {term:"negligence", pos:"noun", def:"failure to take proper care.",
     use:"Uncountable and quite formal: “gross negligence”. Adjective: negligent.",
     examples:["The report found no negligence.","It was negligence rather than sabotage."],
     colloc:"gross negligence · through negligence"},
    {term:"to be bound to", pos:"expression", def:"certain to happen.",
     use:"“Be bound to + verb”: “It was bound to fail eventually.”",
     examples:["With that load, it was bound to overheat.","She’s bound to notice."],
     colloc:"bound to happen · bound to fail"},
    {term:"presumably", pos:"adverb", def:"probably, as far as one can judge.",
     use:"Usually at the start of a clause: “Presumably nobody checked.” A hedge for deductions.",
     examples:["Presumably they ran the tests.","He was, presumably, unaware."],
     colloc:"presumably not · presumably because"},
    {term:"to account for", pos:"phrasal verb", def:"to explain or to be the cause of.",
     use:"Inseparable: “that accounts for the noise”. Also means “to make up a proportion”.",
     examples:["That would account for the pressure drop.","Nothing accounts for the missing hour."],
     colloc:"account for the difference · unaccounted for"},
    {term:"benefit of the doubt", pos:"noun phrase", def:"an assumption of innocence when the evidence is unclear.",
     use:"“Give someone the benefit of the doubt.”",
     examples:["I’d give her the benefit of the doubt.","They gave the crew the benefit of the doubt."],
     colloc:"give someone the benefit of the doubt"} ],
  grammar:[
    {name:"Past modals for degrees of certainty", short:"It must have overheated. It may have been the sensor. It can’t have been sabotage.",
     rule:"To deduce about the past, add “have + past participle” to a modal of certainty. “Must have” is a confident conclusion, “may / might / could have” leave the question open, and “can’t / couldn’t have” reject a possibility.",
     form:["must have + participle → The seal must have failed.","may / might / could have + participle → It might have been a software error.","may not / might not have + participle → She might not have seen the alert.","can’t / couldn’t have + participle → He can’t have known about it.","Continuous: must have been + -ing → They must have been running diagnostics."],
     notes:["The negative of deductive “must” is “can’t”, never “mustn’t”: “mustn’t” means prohibition.","“May not have” and “might not have” express a real possibility that something is untrue.","“Could have” has two readings: a past possibility (“it could have been the cable”) and an unrealised one (“we could have prevented it”). Context decides.","“Should have” in this family means expectation rather than deduction: “The parts should have arrived by now.”","Adverbs do the same job differently: presumably, evidently, possibly, almost certainly."],
     deep:"Deduction is a scale and the modals are the marks along it. At the top, “must have” means you have evidence and have drawn a conclusion — it never means you know for certain, which is exactly why it is honest. In the middle, “may”, “might” and “could have” are practically interchangeable, with “may” a little more formal. At the bottom, English does something asymmetrical that catches learners out: the negative conclusion is “can’t have”, not “mustn’t have”, because prohibition has already claimed that form. Keep two ladders separate in your head — one for deduction, one for rules — and remember that the whole structure contracts heavily in speech (“must’ve”, “can’t’ve”), which makes it far harder to hear than to build. Training your ear on these clusters improves your listening as much as your grammar.",
     chart:{title:"Certainty about the past", cols:["Certainty","Form","Example"], rows:[["~95%","must have + participle","The seal must have failed."],["expectation","should have + participle","The parts should have arrived by now."],["~50%","may / might / could have","It might have been the sensor."],["~20% negative","may not / might not have","She might not have seen it."],["~5%","can’t / couldn’t have","He can’t have known."],["Wrong","mustn’t have","means prohibition, not deduction"]]},
     examples:["The pressure dropped overnight, so a seal must have failed somewhere.","It may have been a software fault, but we can’t rule out the wiring.","She can’t have received the alert — her console was offline.","They must have been running the test when the power cut out."],
     watch:"For a negative deduction use “can’t have”, not “mustn’t have”."},
    {name:"Past modals for judgments and suggestions", short:"They should have checked. We could have prevented it. I would have waited.",
     rule:"The same structure judges past decisions. “Should have” criticises or regrets, “could have” names a missed possibility or a better option, and “would have” states what you yourself would have done in that situation.",
     form:["should / shouldn’t have + participle → They should have run a second test.","could have + participle → We could have caught it earlier.","couldn’t have + participle → They couldn’t have known at that stage.","would / wouldn’t have + participle → I would have waited another day.","ought to have + participle (more formal) → They ought to have reported it."],
     notes:["Always modal + have + participle: never “should had” and never “should of”.","“Should have” criticises the past; “should” alone advises the present.","“Would have” usually implies a condition, stated or unstated: “I would have waited (if it had been my call).”","“Could have” as judgement is softer than “should have”: it suggests an option rather than an obligation.","“Ought to have” is slightly more formal than “should have” and otherwise identical."],
     deep:"These forms let you talk about roads not taken, which is why they carry so much social weight. “They should have checked” assigns fault. “They could have checked” points at a missed option without accusing. “I would have checked” makes it about your own judgement rather than their failure — the diplomatic choice when you are reviewing someone else’s work. In a professional post-mortem, moving between the three is what separates a fair review from an attack, and English speakers read the difference immediately. Structurally there is nothing new: the modal never changes, “have” never changes, and only the participle varies. The persistent errors are orthographic rather than grammatical — “should of” for “should’ve” — and the listening challenge is that all three contract into a single unstressed syllable, so the participle is often the only clue to which modal was used.",
     chart:{title:"Judging past decisions", cols:["Form","Force","Example"], rows:[["should have + participle","criticism / regret","They should have reported it."],["shouldn’t have + participle","criticism of an action","You shouldn’t have signed it."],["ought to have + participle","formal criticism","They ought to have checked."],["could have + participle","missed option, softer","We could have run a second test."],["couldn’t have + participle","exoneration","They couldn’t have known."],["would have + participle","your own judgement","I would have waited."]]},
     examples:["The crew should have logged the anomaly instead of resetting the panel.","We could have avoided the whole delay by ordering a spare in advance.","In fairness, they couldn’t have known the sensor was faulty.","I would have grounded the flight, but it wasn’t my decision."],
     watch:"“Should have”, never “should of” or “should had” — and remember “could have” is softer than “should have”."} ],
  speaking:[
    {kind:"Incident analysis", text:"Given three clues about an unexplained event, produce one deduction with “must have”, two possibilities with “might have”, and one rejection with “can’t have”."},
    {kind:"Fair review", text:"Review a decision that went wrong. Make one “should have”, one “could have”, one “couldn’t have” and one “would have” statement, then decide which was fairest."},
    {kind:"Cold case", text:"One student describes a strange situation from their life. The group speculates using past modals only, until the truth is revealed."} ],
  tips:[
    "Two ladders: deduction (must / might / can’t have) and judgement (should / could / would have).",
    "The negative deduction is “can’t have”, not “mustn’t have”.",
    "Modal + have + participle, always. Never “should of”."],
  quiz:{q:"Her console was offline all night, so she ___ the alert.", options:["can’t have seen","mustn’t have seen","shouldn’t have seen"], answer:0, explain:"A confident negative deduction about the past takes “can’t have + past participle”."} },

{ n:14, title:"ASSEMBLY LINE", classes:"59–60", node:"Sector 14", color:"#4fd18b", theme:"Describing a process, and adding information precisely",
  overview:{
    intro:"Two structures that carry technical writing. The passive describes a process step by step without naming the workers, and modal passives state what must or should be done. Relative clauses then let you add information, and the comma decides whether that information identifies or merely describes.",
    goals:["Describe a process with is/are + past participle and modal + be + past participle.","Sequence process steps with then, next, after that and once.","Distinguish defining from non-defining relative clauses and punctuate them correctly."],
    outcome:"By the end you can write a six-step process description and add three non-defining clauses to a paragraph without breaking its punctuation."
  },
  vocab:[
    {term:"to assemble", pos:"verb", def:"to put the parts of something together.",
     use:"Transitive: “assemble the frame”. Noun: assembly. Frequently passive in process descriptions.",
     examples:["The frames are assembled by hand.","Once the unit is assembled, it’s tested."],
     colloc:"assembly line · assembled by hand"},
    {term:"to inspect", pos:"verb", def:"to examine something carefully and officially.",
     use:"Transitive: “inspect the welds”. Noun: inspection; person: inspector.",
     examples:["Every batch is inspected before shipping.","The welds must be inspected twice."],
     colloc:"a full inspection · inspected for defects"},
    {term:"to sort", pos:"verb", def:"to separate things into groups.",
     use:"Transitive: “sort the components by size”. Also “sort out” = resolve.",
     examples:["The beans are sorted by size and colour.","We sorted out the problem in an hour."],
     colloc:"sort by size · sort out a problem"},
    {term:"to dispose of", pos:"phrasal verb", def:"to get rid of something properly.",
     use:"Inseparable, always with “of”: “dispose of the waste”. Noun: disposal.",
     examples:["Waste must be disposed of safely.","How is the residue disposed of?"],
     colloc:"dispose of waste · safe disposal"},
    {term:"batch", pos:"noun", def:"a quantity produced or processed at one time.",
     use:"Countable: “a batch of components”, “in batches of fifty”.",
     examples:["Each batch is labelled and dated.","We process it in small batches."],
     colloc:"a batch number · in batches"},
    {term:"stage", pos:"noun", def:"one part of a longer process.",
     use:"Countable: “the final stage”, “at this stage”. Slightly more formal than “step”.",
     examples:["At the next stage the parts are coated.","It failed at the testing stage."],
     colloc:"the final stage · a two-stage process"},
    {term:"raw material", pos:"noun phrase", def:"the basic substance from which something is made.",
     use:"Usually plural: “raw materials are delivered weekly”.",
     examples:["The raw materials are sourced locally.","Raw material costs have doubled."],
     colloc:"raw materials · source raw materials"},
    {term:"quality control", pos:"noun phrase", def:"the system for checking standards.",
     use:"Uncountable, often abbreviated QC: “quality control rejected the batch”.",
     examples:["Quality control is carried out at every stage.","It was flagged by quality control."],
     colloc:"strict quality control · pass quality control"},
    {term:"to be labelled", pos:"passive form", def:"to have an identifying label attached.",
     use:"“Each unit is labelled with a serial number.” US spelling: labeled.",
     examples:["Every container is labelled and sealed.","The samples weren’t labelled correctly."],
     colloc:"clearly labelled · labelled with"},
    {term:"whose", pos:"relative pronoun", def:"showing possession inside a relative clause.",
     use:"For people and things: “the supplier whose parts failed”. Never write “who’s”.",
     examples:["The technician whose report we read has left.","A machine whose sensors fail is dangerous."],
     colloc:"whose name · whose fault"} ],
  grammar:[
    {name:"The passive to describe a process", short:"The parts are cleaned, then they are inspected. Each unit must be tested.",
     rule:"A process description uses the present passive, because what matters is the sequence of actions rather than who performs them. Modal passives — must be, should be, can be, has to be — state requirements at each stage.",
     form:["Simple present passive: is / are + past participle → The parts are cleaned in three baths.","Modal passive: modal + be + past participle → Every unit must be tested.","Negative: aren’t + participle / mustn’t be + participle → Waste mustn’t be poured away.","Sequencing: First… Then… Next… After that… Once… Finally…","With “by” only when the agent matters: The samples are checked by an external lab."],
     notes:["The agent is almost never mentioned in a process description — the sequence is the point.","Keep the subject constant where possible, so the reader follows one thing through the chain.","Adverbs of frequency go between “be” and the participle: “Filters are usually replaced monthly.”","Modal passives are the standard form for rules and requirements: “Helmets must be worn”, “Forms should be signed”.","Do not mix “being” into a simple present passive: “is cleaned”, not “is being cleaned”, unless you really mean right now."],
     deep:"Process writing is where the passive stops being a grammar exercise and becomes the obvious choice. Each step keeps the product as its subject — “the beans are picked, washed, dried and sorted” — so the reader tracks one thing through a chain of actions instead of following a cast of workers. That cohesion is the whole point, and it is why manuals, standards and procedure documents are written almost entirely in this form. Modal passives extend it to requirements, which is why every notice you have ever read is built the same way: “tickets must be shown”, “containers should be sealed”. Two practical habits: keep the subject constant so the sequence reads smoothly, and add explicit sequencing words at the joints, because a passive chain without signposts is hard to follow even when every sentence is correct.",
     chart:{title:"Process and requirement forms", cols:["Form","Use","Example"], rows:[["is / are + participle","routine step","The parts are degreased."],["must / has to be + participle","requirement","Each seal must be replaced."],["should / ought to be + participle","recommendation","The filter should be checked weekly."],["can / may be + participle","possibility / permission","Samples may be stored for a week."],["mustn’t be + participle","prohibition","Solvent mustn’t be poured away."],["Sequencers","joining the steps","First… then… after that… finally…"]]},
     examples:["First the components are degreased, then they are dried and inspected.","Every batch must be labelled with a date and a serial number before it is stored.","Once the unit has been assembled, it can be tested at low pressure.","Residue mustn’t be disposed of through the normal drains."],
     watch:"“Is cleaned” for a routine step; “is being cleaned” only for something happening right now."},
    {name:"Defining and non-defining relative clauses", short:"the engineer who signed it · Ana, who signed it,",
     rule:"A defining clause identifies which person or thing you mean and takes no commas. A non-defining clause adds extra information about something already identified, sits between commas, and cannot use “that”.",
     form:["Defining: The engineer who signed the report has left.","Non-defining: Ana Ruiz, who signed the report, has left.","Things: the machine that failed / the machine, which is ten years old,","Possession: the supplier whose parts failed.","Sentence-modifying which: The test failed twice, which delayed the launch."],
     notes:["“That” is impossible in a non-defining clause: use “who” or “which”.","The pronoun of a non-defining clause can never be omitted.","Commas change the facts: “my brother who lives abroad” implies several brothers; “my brother, who lives abroad,” implies one.","“Which” can refer to the whole preceding clause when it adds a comment: “…, which surprised everyone.”","In speech, a non-defining clause is marked by a pause and a change in intonation where the commas would be."],
     deep:"The comma is the whole grammar of this topic. A defining clause is part of the identification, so removing it changes who or what you are talking about; a non-defining clause is a parenthesis, so removing it leaves the sentence intact. Two mechanical consequences follow: “that” is banned from non-defining clauses, and the pronoun can never be dropped there, because the commas have already suspended the main clause and something has to hold the parenthesis together. The consequence for meaning is bigger than most learners expect. “The passengers who had boarded early were moved” says only some passengers were moved; “the passengers, who had boarded early, were moved” says all of them were. In technical and legal writing that difference is not stylistic — it is the sentence’s content, which is why punctuation here deserves real attention.",
     chart:{title:"Defining vs non-defining", cols:["","Defining","Non-defining"], rows:[["Job","identifies which one","adds extra detail"],["Commas","no","yes, both sides"],["“that” allowed?","yes","no"],["Pronoun omission","yes, if object","never"],["Delete the clause?","meaning changes","sentence survives"],["Example","The unit that failed was old.","The unit, which was old, failed."]]},
     examples:["The technician who ran the second test found the fault immediately.","Our main supplier, which has been with us for a decade, missed two deliveries.","The batch that failed inspection was returned; the rest were shipped.","The launch was delayed twice, which cost us the whole quarter."],
     watch:"No “that” in a non-defining clause, and never drop the pronoun when there are commas."} ],
  speaking:[
    {kind:"Process talk", text:"Explain how something is made or done in six present-passive steps, with no agents and with explicit sequencers."},
    {kind:"Rules board", text:"Write the eight requirements of a workshop or lab using modal passives: must be, should be, mustn’t be."},
    {kind:"Comma test", text:"Give your partner five sentences with relative clauses. They must say whether each clause is defining or not, and what the commas would change."} ],
  tips:[
    "Keep the subject constant through a process; let the sequencers do the joining.",
    "Modal passives for every rule: “must be signed”, “should be checked”.",
    "Commas change the facts — decide before you punctuate."],
  quiz:{q:"Every container ___ before it is stored.", options:["must be labelled","must labelled","must be labelling"], answer:0, explain:"A modal passive is modal + be + past participle: “must be labelled”."} },

{ n:15, title:"BRIEFING", classes:"64–65", node:"Sector 15", color:"#5bc8f5", theme:"Recommending impersonally, and checking your listener agrees",
  overview:{
    intro:"Two structures for stating a position. Passive modals make a recommendation sound like a general truth rather than your personal instruction, and tag questions turn a statement into an invitation to agree — the most characteristically English move in conversation.",
    goals:["Give recommendations with passive modals: should be, ought to be, must be, has to be, has got to be.","Choose the right strength of passive modal for the situation.","Form tag questions accurately and use intonation to change their function."],
    outcome:"By the end you can deliver a short set of recommendations in impersonal register and hold a five-turn opinion exchange using tags."
  },
  vocab:[
    {term:"recommendation", pos:"noun", def:"advice about what should be done.",
     use:"Countable: “make a recommendation”, “our recommendations are…”. Verb: recommend.",
     examples:["The report makes four recommendations.","My recommendation is to wait."],
     colloc:"make a recommendation · strong recommendation"},
    {term:"priority", pos:"noun", def:"something that must be dealt with first.",
     use:"Countable: “the top priority”, “set priorities”. “Give priority to + noun”.",
     examples:["Safety has to be the priority.","We need to set clearer priorities."],
     colloc:"top priority · give priority to"},
    {term:"to address (a problem)", pos:"verb", def:"to deal with an issue directly.",
     use:"Transitive: “address the delay”. Common in formal recommendations.",
     examples:["This has to be addressed before the launch.","The report addresses three issues."],
     colloc:"address a problem · properly addressed"},
    {term:"urgent", pos:"adjective", def:"needing immediate attention.",
     use:"For situations, not people: “an urgent repair”. Adverb: urgently.",
     examples:["This is urgent — it must be done today.","The panel needs replacing urgently."],
     colloc:"an urgent matter · a sense of urgency"},
    {term:"to have got to", pos:"semi-modal", def:"an informal, emphatic “must”.",
     use:"“It’s got to be checked.” Common in speech, rare in formal writing.",
     examples:["That’s got to be fixed before Monday.","This has got to stop."],
     colloc:"has got to be · you’ve got to"},
    {term:"ought to", pos:"semi-modal", def:"should — slightly more formal.",
     use:"Always with “to”: “It ought to be reviewed.” Negative: “ought not to”.",
     examples:["The manual ought to be updated.","They ought to have told us."],
     colloc:"ought to be · ought not to"},
    {term:"to bear in mind", pos:"idiom", def:"to remember and consider something.",
     use:"“Bear in mind that…” or “bear it in mind”. Note the spelling: bear, not bare.",
     examples:["Bear in mind that the parts take a week.","It should be borne in mind that costs vary."],
     colloc:"bear in mind that · worth bearing in mind"},
    {term:"feasible", pos:"adjective", def:"possible and practical to do.",
     use:"For plans: “a feasible timeline”. Noun: feasibility.",
     examples:["That isn’t feasible in two weeks.","Is it feasible to run both systems?"],
     colloc:"technically feasible · a feasible option"},
    {term:"to look into", pos:"phrasal verb", def:"to investigate.",
     use:"Inseparable: “this should be looked into”. Very common as a passive recommendation.",
     examples:["The complaint should be looked into.","We’ll look into it this week."],
     colloc:"look into a matter · worth looking into"},
    {term:"surely", pos:"adverb", def:"used to invite agreement about something you consider obvious.",
     use:"Not the same as “certainly”: “Surely that’s not right?” expresses surprise and expects agreement.",
     examples:["Surely they must have noticed?","That surely can’t be the final figure."],
     colloc:"surely not · surely you agree"} ],
  grammar:[
    {name:"Recommendations and opinions with passive modals", short:"It should be reviewed. This has to be dealt with today.",
     rule:"A passive modal states what needs to happen without naming who must do it. The structure is modal + be + past participle, and the choice of modal grades the strength from a suggestion to a requirement.",
     form:["should be / ought to be + participle → The manual should be updated.","must be / has to be + participle → All entries must be signed.","has got to be + participle (informal, emphatic) → This has got to be fixed.","could be / might be + participle (tentative) → The layout could be simplified.","Negative: shouldn’t be / mustn’t be + participle → Passwords mustn’t be shared."],
     notes:["“Should be” and “ought to be” are recommendations; “must be” and “has to be” are requirements.","“Has got to be” is emphatic and informal — natural in speech, out of place in a written report.","The passive removes the agent, which is what makes the recommendation sound objective rather than personal.","Add “by” only when the responsible party matters: “This must be approved by the safety officer.”","“Must be” also means deduction in other contexts (“she must be tired”), so make the recommendation clear from the context."],
     deep:"There is a real difference between “you should update the manual” and “the manual should be updated”. The first is your instruction to a person; the second is a statement about the world, and it lands as an assessment rather than an order. That is why passive modals dominate reports, audits and reviews: they let you be firm about the action while staying neutral about the actor. The grading is what makes them useful. “Could be” floats an option, “should be” recommends, “has to be” states a requirement, and “has got to be” adds emotional pressure that belongs only in speech. Two mechanics keep them clean: the modal never changes form, so all the work is done by “be” plus the participle, and the negatives shift meaning rather than fading — “shouldn’t be shared” is advice, “mustn’t be shared” is a prohibition.",
     chart:{title:"Strength of passive modals", cols:["Form","Strength","Example"], rows:[["could / might be + participle","tentative option","The form could be simplified."],["should be + participle","recommendation","The manual should be updated."],["ought to be + participle","recommendation, formal","The policy ought to be reviewed."],["has to be + participle","requirement (external rule)","Every entry has to be signed."],["must be + participle","requirement (strong)","Waste must be disposed of safely."],["has got to be + participle","emphatic, informal","This has got to be sorted out."]]},
     examples:["The checklist should be revised before the next inspection.","All maintenance records have to be signed by a supervisor.","This has got to be dealt with today — we can’t run another shift like that.","Access codes mustn’t be shared, and they ought to be changed monthly."],
     watch:"Modal + be + past participle: “should be updated”, never “should updated” or “should be update”."},
    {name:"Tag questions for opinions", short:"That’s the real problem, isn’t it?",
     rule:"A tag question turns a statement into a check. Repeat the auxiliary, reverse the polarity, and use a pronoun. Positive statements take negative tags and negative statements take positive tags.",
     form:["Positive statement, negative tag: You’ve seen the report, haven’t you?","Negative statement, positive tag: You haven’t seen it, have you?","No auxiliary → use do: She works upstairs, doesn’t she?","With modals: It should be replaced, shouldn’t it?","Irregular: I’m late, aren’t I? · Let’s start, shall we? · Nobody called, did they?"],
     notes:["Intonation changes the function: falling intonation asks for agreement, rising intonation asks a genuine question.","The tag repeats the auxiliary of the statement: “I’ve finished, haven’t I?”, “She left, didn’t she?”.","Indefinite subjects take “they” in the tag: “Nobody noticed, did they?”, “Everyone agreed, didn’t they?”","Imperatives take “will you” or “would you”: “Close the door, will you?”","“I am” has the irregular tag “aren’t I?”, not “amn’t I”."],
     deep:"Tags are what make English conversation feel collaborative. Instead of asserting a view and waiting, a speaker states it and immediately invites the other person in — “that was the real problem, wasn’t it?” — which converts a monologue into an exchange. The grammar is mechanical and can be automated with practice: find the auxiliary, flip the polarity, add the pronoun. What learners underestimate is intonation, because it carries the whole function. Falling intonation means you expect agreement and are really seeking confirmation; rising intonation means you genuinely do not know. Use the wrong one and you either sound as though you are interrogating a colleague or as though you have already decided their answer. Learn the irregular handful — “aren’t I”, “shall we”, “will you”, “did they” after nobody — and the rest follows from the auxiliary.",
     chart:{title:"Tag question forms", cols:["Statement","Tag","Note"], rows:[["It should be replaced,","shouldn’t it?","modal repeated"],["You’ve read it,","haven’t you?","positive → negative"],["You haven’t read it,","have you?","negative → positive"],["She works here,","doesn’t she?","no auxiliary → do"],["I’m next,","aren’t I?","irregular"],["Nobody objected,","did they?","indefinite → they"],["Let’s begin,","shall we?","suggestion"]]},
     examples:["That’s the real bottleneck, isn’t it?","You haven’t signed the log yet, have you?","This ought to be reviewed before Friday, oughtn’t it?","Nobody actually tested it under load, did they?"],
     watch:"The tag repeats the statement’s auxiliary and reverses the polarity: “I’m right, aren’t I?”, never “amn’t I”."} ],
  speaking:[
    {kind:"Audit report", text:"Deliver six recommendations about a place you know, using a different passive modal each time, from tentative to mandatory."},
    {kind:"Opinion exchange", text:"Hold a five-turn conversation about a current issue. Every turn must end with a tag question, and your partner must respond before adding their own."},
    {kind:"Intonation drill", text:"Say the same tag question twice — once seeking agreement, once genuinely asking. Your partner identifies which was which."} ],
  tips:[
    "Passive modals make advice sound objective — use them in reports.",
    "Grade the strength deliberately: could be, should be, has to be.",
    "The tag repeats the auxiliary; intonation decides whether it is a check or a question."],
  quiz:{q:"The whole procedure ___ before the next audit, ___ ?", options:["should be reviewed / shouldn’t it","should review / should it","should be review / isn’t it"], answer:0, explain:"A passive modal takes “be” plus a past participle, and the tag repeats the same modal with reversed polarity."} },

{ n:16, title:"LOGBOOK", classes:"68–69", node:"Sector 16", color:"#e8a33d", theme:"What you have achieved, and what you intend to achieve",
  overview:{
    intro:"The last sector closes the log. First, accomplishments: the simple past for finished achievements and the present perfect for what you have done in a period that is still open. Then goals: the future perfect for what you will have completed, and “would like to have + participle” for the ambitions you hope to look back on.",
    goals:["Talk about accomplishments with the simple past and the present perfect.","Set goals with the future perfect.","Express hoped-for achievements with would like to have + past participle."],
    outcome:"By the end you can present your achievements in a two-minute personal statement and set three dated goals in precise future forms."
  },
  vocab:[
    {term:"accomplishment", pos:"noun", def:"something impressive that you have achieved.",
     use:"Countable: “a major accomplishment”. Verb: accomplish. British English often prefers “achievement”.",
     examples:["Finishing the course was a real accomplishment.","Her accomplishments speak for themselves."],
     colloc:"a major accomplishment · a sense of accomplishment"},
    {term:"to achieve", pos:"verb", def:"to succeed in doing something after effort.",
     use:"Takes goals and results, not objects: “achieve a target”, not “achieve a car”.",
     examples:["We achieved everything we planned.","She has achieved a lot in two years."],
     colloc:"achieve a goal · achieve success"},
    {term:"to set a goal", pos:"expression", def:"to decide on something you want to achieve.",
     use:"“Set a goal”, not “put a goal”. “Reach” or “meet” a goal when you succeed.",
     examples:["I set myself three goals for this year.","We met every goal except one."],
     colloc:"set a goal · reach a goal · realistic goals"},
    {term:"so far", pos:"adverbial phrase", def:"up to now, in a period still open.",
     use:"A present perfect signal, usually at the end: “I’ve completed four modules so far.”",
     examples:["So far I’ve visited eleven countries.","Nothing has gone wrong so far."],
     colloc:"so far so good · so far this year"},
    {term:"to qualify", pos:"verb", def:"to gain the official right to do a job.",
     use:"“Qualify as + profession” or “qualify for + noun”: “qualify as an engineer”.",
     examples:["She qualified as a paramedic last year.","I don’t qualify for the grant."],
     colloc:"qualify as · newly qualified"},
    {term:"milestone", pos:"noun", def:"an important point in a plan or a life.",
     use:"Countable: “reach a milestone”, “a major milestone”.",
     examples:["Publishing it was a milestone for the team.","The next milestone is certification."],
     colloc:"reach a milestone · a major milestone"},
    {term:"to look back on", pos:"phrasal verb", def:"to think about something in your past.",
     use:"Three parts: “look back on my twenties”. Pairs naturally with “would like to have”.",
     examples:["I’d like to look back on this as a turning point.","She looks back on it fondly."],
     colloc:"look back on it · looking back"},
    {term:"in the long run", pos:"adverbial phrase", def:"over a long period in the future.",
     use:"Usually at the start or end: “In the long run, it will save money.”",
     examples:["In the long run, the investment pays off.","It’s cheaper in the long run."],
     colloc:"in the long run · in the short term"},
    {term:"to fall short of", pos:"expression", def:"to fail to reach a standard or target.",
     use:"“Fall short of expectations / the target”.",
     examples:["We fell short of the target by two per cent.","It fell short of what we expected."],
     colloc:"fall short of the target"},
    {term:"realistic", pos:"adjective", def:"sensible and possible in practice.",
     use:"For goals and plans: “a realistic timeline”. Opposite: unrealistic.",
     examples:["Is that a realistic goal for six months?","Be realistic about how long it takes."],
     colloc:"a realistic target · perfectly realistic"} ],
  grammar:[
    {name:"Accomplishments with the simple past and present perfect", short:"I finished the course in May. / I’ve completed four modules so far.",
     rule:"The simple past reports an achievement inside a finished period of time. The present perfect reports it inside a period that is still open, or with no time reference at all when only the result matters.",
     form:["Simple past + finished time → I qualified in 2021. / I finished it last month.","Present perfect + open period → I’ve completed three projects this year.","Present perfect, no time → I’ve worked in four countries.","With for and since → I’ve worked here for six years / since 2019.","Experience question then detail: Have you ever led a team? — Yes, I led one in 2022."],
     notes:["Once you name a finished time, the present perfect is impossible: “I have qualified in 2021” is wrong.","Open-period markers pull the perfect: today, this week, this year, so far, in my career, ever, never, already, yet.","In interviews and personal statements the pattern is perfect first, past second: claim the experience, then date it.","“For” + duration and “since” + starting point both need the present perfect when the situation continues.","Counted results take the perfect in an open period: “I’ve delivered eight sessions this term.”"],
     deep:"Stop asking when it happened and ask whether the box is closed. The simple past puts an achievement in a closed box — last year, in 2021, during my degree — and boxes like that cannot receive anything else. The present perfect puts it in a box that is still on the table: this year, in my career, so far. That is why “I’ve completed three modules this term” makes sense and “I’ve completed three modules last term” does not. In practice the two work as a team, and the sequence matters professionally: open with the perfect to establish that you have the experience, then switch to the past to give the specifics. “I’ve managed remote teams. I led a team of six in 2022” is exactly the rhythm an interviewer expects, and reversing it makes a strong record sound like an anecdote.",
     chart:{title:"Which tense for an achievement?", cols:["Time frame","Tense","Example"], rows:[["finished period (in 2021, last year)","simple past","I qualified in 2021."],["open period (this year, so far)","present perfect","I’ve run four workshops this year."],["whole life, no date","present perfect","I’ve worked in three countries."],["duration continuing","present perfect + for/since","I’ve been here since 2019."],["experience question","present perfect","Have you ever managed a budget?"],["details of that experience","simple past","Yes — I managed one in 2022."]]},
     examples:["I’ve led three projects so far this year, and the first one finished ahead of schedule.","She qualified as an engineer in 2019 and has worked in maintenance ever since.","Have you ever presented to a board? — Yes, I did it twice last spring.","We haven’t missed a deadline this quarter, though we missed two last year."],
     watch:"Never combine finished time with the present perfect: “I finished it last month”, not “I have finished it last month”."},
    {name:"Goals with the future perfect and would like to have + past participle", short:"By June I’ll have finished. / I’d like to have travelled more by then.",
     rule:"The future perfect states what will be complete before a future point. “Would like to have + past participle” expresses a hoped-for achievement — what you want to be able to look back on — and is softer and less certain than the future perfect.",
     form:["will have + past participle → By December I’ll have completed the certification.","will have been + -ing (duration) → By May I’ll have been studying for two years.","would like to have + participle → I’d like to have published something by thirty.","would like to be + -ing → In five years I’d like to be running my own team.","hope to have + participle → I hope to have finished by then."],
     notes:["The future perfect needs a future reference point: by then, by June, by the time I’m thirty.","After “by the time”, the verb stays in the present: “By the time I’m thirty, I’ll have finished.”","“Would like to have + participle” is about desire, not prediction — it does not claim the goal will be met.","“I’d like to have finished” and “I’d like to finish” differ: the first looks back from a future point, the second looks forward from now.","State verbs stay simple: “I’ll have known her ten years”, not “will have been knowing”."],
     deep:"These two forms let you talk about the future from two different vantage points. The future perfect stands at a future date and looks back at completed work — “by the end of the year we’ll have replaced every unit” — which is why it is the language of plans, targets and project reporting. “Would like to have + participle” stands at the same future date but reports a wish rather than a projection: “I’d like to have moved into research by then.” The difference is confidence, and choosing correctly matters in an interview or a review, because the future perfect commits you and the “would like” form does not. Note the recurring rule one last time: after “by the time”, the verb stays in the present, because English marks the future only once, in the main clause. That single principle has run through half of this level.",
     chart:{title:"Talking about future achievements", cols:["Form","Certainty","Example"], rows:[["will have + participle","confident projection","By June I’ll have finished the course."],["will have been + -ing","duration up to a point","By May I’ll have been working here a year."],["hope to have + participle","hopeful","I hope to have qualified by then."],["would like to have + participle","desire, uncommitted","I’d like to have travelled more by thirty."],["would like to be + -ing","desired situation","I’d like to be leading a team in five years."],["by the time + present","sets the deadline","By the time I’m thirty…"]]},
     examples:["By the end of next year I’ll have completed both certifications.","By the time the refit finishes, we’ll have been working on it for eight months.","I’d like to have moved into project management by the time I’m thirty.","In five years I’d like to be running my own maintenance team, and I hope to have trained a few people by then."],
     watch:"After “by the time” the verb stays in the present, and “would like to have + participle” expresses a wish, not a prediction."} ],
  speaking:[
    {kind:"Personal statement", text:"Present your achievements in two minutes. Open each claim in the present perfect and follow it with a dated detail in the simple past."},
    {kind:"Five-year log", text:"Set three dated goals using the future perfect, then restate each one with “would like to have”. Discuss which version feels more honest."},
    {kind:"Peer review", text:"Interview your partner about their record and their plans. Every question must use one of this sector’s structures."} ],
  tips:[
    "Closed time takes the past; open time takes the perfect.",
    "Claim the experience in the perfect, then date it in the past.",
    "After “by the time”, stay in the present."],
  quiz:{q:"By the time the refit is over, we ___ on it for eight months.", options:["will have been working","will work","have been working"], answer:0, explain:"Duration up to a future point takes the future perfect continuous, and “by the time” keeps its own clause in the present."} }
);
